import {isNRF52} from './unified-project.js';
export function installNRF52Keyboard({getProject,getSnapshot,showDialog,send,setPressed}){
 const button=document.createElement('button');button.id='nrf-keyboard';button.textContent='USB / BLE Klavye';button.title='nRF52840 sanal klavye alıcısı';document.getElementById('bluetooth-network').after(button);
 button.onclick=()=>{showDialog('nRF52840 · USB / BLE klavye alıcısı',`<div data-nrf-keyboard-panel><p data-kbd-backend style="border-left:3px solid #779d98;padding-left:10px"></p><p>Firmware tuş raporlarını bu sanal alıcıya gönderir. Bilgisayarınıza tuş basılmaz; gerçek USB aygıtı veya Bluetooth radyo bağlantısı oluşturulmaz.</p><p>Projeler → <strong>nRF52840 · NimBLE güvenli BLE klavye, TinyUSB C17 klavye veya USB / BLE klavye</strong> örneğini açın, Çalıştır’a basın ve aşağıdaki alıcıları bağlayın. Devredeki A / B / Shift butonlarını kullanın.</p><div class="dialog-actions"><strong>Devre tuşları</strong><button data-kbd-key="keyA">A</button><button data-kbd-key="keyB">B</button><button data-kbd-key="keyShift">Shift</button></div><small>Bu tuşlar hazır örneğin gerçek tact/GPIO girişlerini değiştirir. Paneli kapatıp devredeki butonları da kullanabilirsiniz.</small>${['usb','ble'].map(t=>`<section data-kbd-section="${t}" style="border:1px solid #526273;padding:14px;margin:12px 0;border-radius:6px"><h3>${t==='usb'?'USB HID · sanal host':'Bluetooth LE HID · sanal GATT'}</h3><p data-kbd-status="${t}" role="status"></p><div class="dialog-actions"><button data-kbd-action="connect" data-transport="${t}">${t==='usb'?'USB bağla':'BLE bağlan'}</button><button data-kbd-action="disconnect" data-transport="${t}">Bağlantıyı kes</button><button data-kbd-action="caps" data-transport="${t}">Caps Lock</button><button data-kbd-action="clear" data-transport="${t}">Çıktıyı temizle</button></div>${t==='ble'?'<div data-ble-pair hidden style="border:1px solid #779d98;padding:12px;margin:12px 0"><strong>Güvenli eşleştirme · Sayıları karşılaştırın</strong><p>Klavye: <code data-ble-device-code style="font-size:22px;letter-spacing:2px"></code> · Alıcı: <code data-ble-receiver-code style="font-size:22px;letter-spacing:2px"></code></p><p>İki sanal aygıtın kodları aynıysa kabul edin. Onayınız gerçek NimBLE SMP işlemine iletilir.</p><div class="dialog-actions"><button data-ble-confirm="yes">Kodlar aynı · Kabul et</button><button data-ble-confirm="no">Reddet</button></div></div><p data-ble-security></p><details data-ble-trace-wrap hidden><summary>BLE protokol akışı</summary><pre data-ble-trace style="white-space:pre-wrap"></pre></details><label style="display:block;margin:10px 0"><input type="checkbox" data-kbd-subscribe checked> Tuş bildirimlerine abone ol (CCCD)</label>':''}<label style="display:block;margin-top:10px">Alınan metin<textarea data-kbd-text="${t}" readonly aria-label="${t==='usb'?'USB':'BLE'} alınan tuşlar" rows="3" style="width:100%;background:#101c28;color:#f2f6fa;padding:10px;font:18px monospace"></textarea></label>${t==='usb'?'<div class="dialog-actions"><button data-kbd-action="suspend" data-transport="usb">USB suspend</button><button data-kbd-action="resume" data-transport="usb">USB resume</button><button data-kbd-action="boot" data-transport="usb">Boot protokolü</button></div><details><summary>USB kontrol aktarımı</summary><pre data-usb-trace style="white-space:pre-wrap"></pre></details>':''}<pre data-kbd-report="${t}" style="white-space:pre-wrap"></pre></section>`).join('')}<details><summary>Desteklenen kapsam ve API</summary><p>C17 <code>#include &lt;wirevo_keyboard.h&gt;</code>: USB/BLE begin, ready, report, release, leds ve end. 8 bayt rapor: modifier, 0, altı tuş usage kodu. US klavye düzeni; Ctrl/Alt/GUI ham olay olarak kaydedilir.</p><p>TinyUSB C17 örneğinde özgün TinyUSB 0.18.0 çekirdeği ve HID sınıfı ARM üzerinde çalışır; denetleyici Wirevo sanal DCD portudur. Diğer USB/BLE örneği Wirevo C API’sini kullanır. Nordic USBD/RADIO yazmaç sürücüsü, SoftDevice ve ZMK/Zephyr desteği yoktur. NimBLE örneğinde gerçek C ATT/GATT/SMP, Secure Connections sayısal karşılaştırma, P-256 ECDH ve AES-CCM çalışır. Bond anahtarları yalnız oturum RAM’indedir; reset veya yeniden derleme eşleştirmeyi siler. Fiziksel RF ve işletim sistemine klavye bağlantısı yoktur.</p><a href="./notices/NRF52-NIMBLE.md" target="_blank">NimBLE eşleştirme ve sınırlar</a> · <a href="./notices/NRF52-TINYUSB.md" target="_blank">TinyUSB profili ve sınırlar</a> · <a href="./notices/NRF52-KEYBOARD.md" target="_blank">API, örnek ve sınırlar</a></details></div>`);
 const panel=document.querySelector('[data-nrf-keyboard-panel]');panel.querySelectorAll('[data-kbd-key]').forEach(b=>{const press=v=>{setPressed?.(b.dataset.kbdKey,v);b.setAttribute('aria-pressed',String(v));};b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);press(true);};b.onpointerup=()=>press(false);b.onpointercancel=()=>press(false);b.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();press(true);}};b.onkeyup=e=>{if(['Enter',' '].includes(e.key))press(false);};b.onblur=()=>press(false);});panel.querySelectorAll('[data-kbd-action]').forEach(b=>b.onclick=()=>{const t=b.dataset.transport,c=getSnapshot()?.keyboard?.[t],action=b.dataset.kbdAction;send({type:'keyboard',transport:t,action:action==='caps'?'leds':action==='boot'?'protocol':action,...(action==='caps'?{value:(c?.leds||0)^2}:action==='boot'?{value:0}:{})});});panel.querySelectorAll('[data-ble-confirm]').forEach(b=>b.onclick=()=>send({type:'keyboard',transport:'ble',action:'confirm',accept:b.dataset.bleConfirm==='yes'}));panel.querySelector('[data-kbd-subscribe]').onchange=e=>send({type:'keyboard',transport:'ble',action:'subscribe',enabled:e.target.checked});render();};
 function render(){const available=isNRF52(getProject());button.hidden=!available;const panel=document.querySelector('[data-nrf-keyboard-panel]');if(!panel||!available)return;const k=getSnapshot()?.keyboard,dcd=k?.usbDCD,ble=k?.nimble;panel.querySelector('[data-kbd-section="usb"]').hidden=!!ble?.enabled;const pair=panel.querySelector('[data-ble-pair]');pair.hidden=!ble?.pairing;panel.querySelector('[data-ble-device-code]').textContent=ble?.deviceCode||'—';panel.querySelector('[data-ble-receiver-code]').textContent=ble?.receiverCode||'—';panel.querySelector('[data-ble-security]').textContent=ble?.enabled?(ble.authenticated?'Secure Connections · doğrulanmış · AES-CCM şifreli · '+(ble.bonded?'oturum bond kaydı var':'bond bekleniyor'):ble.pairing?'Onay bekleniyor; korunan HID verisi henüz okunamaz.':ble.error?'Eşleştirme / GATT hatası: '+ble.error:'NimBLE alıcısı '+(ble.ready?'hazır':'hazırlanıyor')):'';panel.querySelector('[data-ble-trace-wrap]').hidden=!ble?.enabled;panel.querySelector('[data-ble-trace]').textContent=ble?.enabled?ble.trace.join('\n')+'\n'+ble.encryptedPackets+' şifreli paket · Anahtarlar: yalnız RAM':'';panel.querySelector('[data-kbd-backend]').textContent=ble?.enabled?'BLE: gerçek Apache NimBLE 1.8.0 firmware yığını · sanal HCI · güvenli eşleştirme ve şifreli HIDS.':dcd?.enabled?'USB: gerçek TinyUSB 0.18.0 firmware yığını / Wirevo sanal DCD. BLE: ayrı, Wirevo sanal servisi.':'USB/BLE: Wirevo sanal klavye C API. TinyUSB yığını için TinyUSB C17 örneğini açın.';panel.querySelector('[data-usb-trace]').textContent=dcd?.enabled?(dcd.trace.join('\n')+'\n'+JSON.stringify(dcd.descriptors)):'';for(const t of ['usb','ble']){const c=k?.[t];panel.querySelector(`[data-kbd-status="${t}"]`).textContent=t==='usb'&&dcd?.enabled&&dcd.connected&&!dcd.configured?(dcd.trace.at(-1)?.startsWith('ERROR')?'USB hata: '+dcd.trace.at(-1):'USB tanınması sürüyor; firmware kontrol isteklerini işliyor.'):!c?.initialized?'Firmware servisi henüz başlamadı.':c.connected?'Bağlı'+(t==='ble'?(c.subscribed?' · Bildirim açık':' · Bildirim kapalı'):' · Yapılandırma 1 · IN 0x81'):t==='ble'?'Reklam yayını hazır · '+c.name:'USB klavye hazır · alıcı bağlı değil';const text=panel.querySelector(`[data-kbd-text="${t}"]`);if(text.value!==(c?.text||''))text.value=c?.text||'';panel.querySelector(`[data-kbd-report="${t}"]`).textContent=c?`Rapor: ${c.report.map(x=>x.toString(16).padStart(2,'0')).join(' ')}\n${c.reports} rapor · Caps Lock ${c.leds&2?'açık':'kapalı'}\nSon olay: ${JSON.stringify(c.events.at(-1)||{})}`:'';for(const b of panel.querySelectorAll(`[data-transport="${t}"]`)){const a=b.dataset.kbdAction;if(t==='usb'&&dcd?.enabled)b.disabled=a==='connect'?dcd.connected:a==='disconnect'?!dcd.connected:a==='resume'?!dcd.suspended:a==='suspend'?!dcd.configured||dcd.suspended:['caps','boot'].includes(a)?!dcd.configured||dcd.suspended:false;else b.disabled=a==='connect'?!c?.initialized||c.connected:['disconnect','caps'].includes(a)?!c?.connected:['suspend','resume','boot'].includes(a);}
;}const sub=panel.querySelector('[data-kbd-subscribe]');sub.checked=!!k?.ble?.subscribed;sub.disabled=!k?.ble?.connected||ble?.enabled&&!ble.authenticated;}
 return{render};
}
